<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>T-Minus Brutalist Fintech</title>
    <style>
        :root {
            --bg-color: #F2EFE9;
            --text-color: #111111;
            --accent-lime: #D4FF55; /* Approximate lime */
            --border-width: 1.5px;
            --font-display: 'Anton', 'Impact', sans-serif;
            --font-body: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --font-mono: "SF Mono", "Roboto Mono", "Courier New", monospace;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: var(--font-body);
            line-height: 1.5;
            -webkit-font-smoothing: antialiased;
            overflow-x: hidden;
        }

        /* Utilities */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 0 40px;
        }

        .section-divider {
            height: var(--border-width);
            background-color: var(--text-color);
            width: 100%;
            margin: 60px 0;
        }

        /* Typography */
        h1 {
            font-family: var(--font-display);
            font-size: clamp(3rem, 6vw, 5rem);
            text-transform: uppercase;
            letter-spacing: -1px;
            line-height: 1;
            margin-bottom: 40px;
        }

        .label-pill {
            display: inline-block;
            border: var(--border-width) solid var(--text-color);
            border-radius: 50px;
            padding: 6px 16px;
            font-family: var(--font-mono);
            font-size: 10px;
            text-transform: uppercase;
            letter-spacing: 1px;
            margin-bottom: 24px;
            background: transparent;
        }

        .mono-text {
            font-family: var(--font-mono);
            font-size: 12px;
            color: #666;
            letter-spacing: 0.5px;
        }

        strong.mono-bold {
            font-family: var(--font-mono);
            font-weight: 700;
            color: #000;
        }

        /* Header */
        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 24px 40px;
            border-bottom: var(--border-width) solid var(--text-color);
            position: sticky;
            top: 0;
            background: var(--bg-color);
            z-index: 100;
        }

        .logo {
            font-family: var(--font-display);
            font-size: 20px;
            font-weight: 400;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo-icon {
            width: 24px;
            height: 24px;
            border: 2px solid black;
            border-radius: 50%;
            position: relative;
        }
        .logo-icon::after {
            content: '';
            position: absolute;
            top: 4px;
            left: 4px;
            width: 12px;
            height: 6px;
            border-top: 2px solid var(--accent-lime);
            border-right: 2px solid var(--accent-lime);
            transform: rotate(45deg);
        }

        nav ul {
            display: flex;
            gap: 32px;
            list-style: none;
        }

        nav a {
            text-decoration: none;
            color: #888;
            font-family: var(--font-mono);
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1px;
            transition: color 0.2s;
        }

        nav a:hover { color: var(--text-color); }

        .btn-primary {
            background: var(--text-color);
            color: white;
            padding: 12px 24px;
            border-radius: 30px;
            font-family: var(--font-mono);
            font-size: 11px;
            text-decoration: none;
            text-transform: uppercase;
            letter-spacing: 1px;
            transition: transform 0.1s;
        }
        .btn-primary:hover { transform: scale(1.02); }

        /* Section 1: Mental Model */
        .mental-model-section {
            padding: 80px 0;
        }

        .cards-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
            margin-top: 48px;
        }

        .card {
            background: transparent;
            border: var(--border-width) solid var(--text-color);
            border-radius: 16px;
            padding: 32px 24px;
            position: relative;
            display: flex;
            flex-direction: column;
            min-height: 320px; /* Enforce equal heights */
            overflow: hidden;
            transition: transform 0.2s;
        }

        .card:hover {
            transform: translateY(-4px);
            box-shadow: 4px 4px 0 rgba(0,0,0,0.1);
        }

        .card-bg-num {
            position: absolute;
            top: 16px;
            right: 16px;
            font-family: var(--font-display);
            font-size: 80px;
            opacity: 0.05;
            line-height: 1;
            pointer-events: none;
            user-select: none;
        }

        .card-icon {
            width: 48px;
            height: 48px;
            border: var(--border-width) solid var(--text-color);
            border-radius: 12px;
            margin-bottom: 24px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 20px;
            position: relative;
            z-index: 2;
        }

        /* Specific icon tweaks for visual match */
        .icon-clock::before { content: '🕒'; filter: grayscale(1); }
        .icon-target::before { content: '◎'; font-size: 24px; color: var(--accent-lime); } 
        .icon-chart::before { content: '〰'; font-size: 24px; transform: rotate(-15deg); }
        .icon-doc::before { content: '☰'; font-size: 18px; }

        .card-meta {
            font-family: var(--font-mono);
            font-size: 11px;
            color: #888;
            margin-bottom: 8px;
            z-index: 2;
        }

        .card-title {
            font-family: var(--font-display);
            font-size: 22px;
            text-transform: uppercase;
            margin-bottom: 16px;
            line-height: 1.1;
            z-index: 2;
        }

        .card-desc {
            font-size: 14px;
            color: #444;
            line-height: 1.6;
            z-index: 2;
            flex-grow: 1; /* Pushes footer if needed, though not strictly in screenshot */
        }

        .card-footer-nav {
            margin-top: 60px;
            text-align: center;
            font-family: var(--font-mono);
            font-size: 10px;
            color: #999;
            letter-spacing: 1px;
            text-transform: uppercase;
        }

        /* Section 2: Lifecycle / Transit Map */
        .lifecycle-section {
            padding: 80px 0 120px 0;
        }

        .intro-text {
            max-width: 600px;
            font-size: 16px;
            color: #555;
            margin-bottom: 48px;
        }

        .transit-map-container {
            border: var(--border-width) solid var(--text-color);
            border-radius: 20px;
            padding: 48px;
            background: rgba(255,255,255,0.3);
            box-shadow: 8px 8px 0 rgba(0,0,0,0.05);
            position: relative;
        }

        /* The Rail Line */
        .rail-wrapper {
            position: relative;
            height: 80px;
            margin: 0 40px;
            display: flex;
            align-items: center;
        }

        .rail-line-bg {
            position: absolute;
            top: 50%;
            left: 0;
            right: 0;
            height: 2px;
            background: var(--text-color);
            z-index: 1;
        }

        .rail-line-future {
            position: absolute;
            top: 50%;
            left: 42%; /* Starts after "You are here" */
            right: 0;
            height: 2px;
            background: repeating-linear-gradient(
                to right,
                var(--accent-lime) 0,
                var(--accent-lime) 6px,
                transparent 6px,
                transparent 12px
            );
            z-index: 1;
        }

        /* Stations */
        .station {
            position: absolute;
            top: 50%;
            transform: translate(-50%, -50%);
            z-index: 2;
            display: flex;
            flex-direction: column;
            align-items: center;
            width: 120px; /* Space for labels */
        }

        .dot {
            width: 14px;
            height: 14px;
            background: var(--text-color);
            border-radius: 50%;
            border: 2px solid var(--bg-color);
            box-shadow: 0 0 0 1px var(--text-color);
        }

        .dot.active {
            background: var(--accent-lime);
            border-color: var(--text-color);
            box-shadow: 0 0 0 2px var(--accent-lime), 0 0 0 4px var(--text-color);
        }

        .diamond {
            width: 16px;
            height: 16px;
            background: var(--accent-lime);
            transform: rotate(45deg) translate(-50%, -50%); /* Adjust for centering */
            position: absolute;
            top: 50%;
            left: 50%;
            border: 2px solid var(--text-color);
        }

        .hollow-circle {
             width: 14px;
             height: 14px;
             border: 2px solid #FF6B6B; /* Red accent for expiry */
             border-radius: 50%;
             background: transparent;
        }

        .label-top {
            position: absolute;
            bottom: 24px;
            text-align: center;
            width: 100%;
        }

        .label-title {
            font-family: var(--font-mono);
            font-size: 9px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--text-color);
            display: block;
            margin-bottom: 2px;
        }

        .label-sub {
            font-family: var(--font-mono);
            font-size: 9px;
            color: #999;
            display: block;
        }

        .label-bottom {
            position: absolute;
            top: 24px;
            text-align: center;
            width: 100%;
        }

        /* Station Positions (Percentages) */
        .st-1 { left: 0%; }
        .st-2 { left: 15%; }
        .st-3 { left: 42%; } /* You are here */
        .st-4 { left: 82%; } /* Deadline */
        .st-5 { left: 98%; } /* Expiry */

        /* Map Info Footer */
        .map-info {
            margin-top: 60px;
            border-top: 1px dashed #ccc;
            padding-top: 32px;
            display: grid;
            grid-template-columns: 1fr 1fr 1.5fr;
            gap: 40px;
        }

        .info-col h4 {
            font-family: var(--font-mono);
            font-size: 10px;
            text-transform: uppercase;
            color: #888;
            margin-bottom: 12px;
            letter-spacing: 1px;
        }

        .countdown-val {
            font-family: var(--font-mono);
            font-size: 24px;
            font-weight: 700;
            color: var(--text-color);
        }

        .tranche-tags {
            display: flex;
            gap: 8px;
            flex-wrap: wrap;
        }

        .tag {
            border: 1px solid #aaa;
            border-radius: 12px;
            padding: 4px 12px;
            font-family: var(--font-mono);
            font-size: 10px;
            color: #666;
        }

        .promise-text {
            font-size: 13px;
            color: #444;
            line-height: 1.5;
        }

        .promise-text strong {
            color: #000;
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .cards-grid { grid-template-columns: repeat(2, 1fr); }
            .map-info { grid-template-columns: 1fr; gap: 32px; }
            .rail-wrapper { margin: 0 20px; overflow-x: auto; }
        }

        @media (max-width: 768px) {
            header { padding: 16px 20px; }
            nav { display: none; } /* Simplified for mobile view based on typical brutalist patterns */
            .container { padding: 0 20px; }
            .cards-grid { grid-template-columns: 1fr; }
            .transit-map-container { padding: 24px 16px; overflow-x: scroll; }
            .rail-wrapper { width: 800px; min-width: 100%; } /* Force horizontal scroll on map if needed */
        }
    </style>
</head>
